package com.tekwatt.payment.controller;import com.tekwatt.payment.dto.*;import com.tekwatt.payment.entity.*;import com.tekwatt.payment.service.PaymentOperationsService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/payments/operations")public class PaymentOperationsController{private final PaymentOperationsService service;public PaymentOperationsController(PaymentOperationsService s){service=s;}@GetMapping("/gateways")List<GatewayConfigResponse>gateways(@RequestParam UUID tenantId){return service.gateways(tenantId);}@PutMapping("/gateways")GatewayConfigResponse gateway(@RequestParam UUID tenantId,@Valid@RequestBody GatewayConfigRequest r){return service.gateway(tenantId,r);}@PostMapping("/wallets")@ResponseStatus(HttpStatus.CREATED)Wallet wallet(@Valid@RequestBody CreateWalletRequest r){return service.createWallet(r);}@GetMapping("/wallets")List<Wallet>wallets(@RequestParam UUID tenantId){return service.wallets(tenantId);}@GetMapping("/wallets/{id}/entries")List<WalletEntry>entries(@PathVariable UUID id){return service.entries(id);}@PostMapping("/wallets/{id}/adjustments")Wallet adjust(@PathVariable UUID id,@Valid@RequestBody WalletAdjustmentRequest r){return service.adjust(id,r);}@PostMapping("/scan-pay-orders")@ResponseStatus(HttpStatus.CREATED)ScanPayOrder order(@Valid@RequestBody CreateScanPayOrderRequest r){return service.createOrder(r);}@GetMapping("/scan-pay-orders")List<ScanPayOrder>orders(@RequestParam UUID tenantId){return service.orders(tenantId);}@PatchMapping("/scan-pay-orders/{id}")ScanPayOrder update(@PathVariable UUID id,@Valid@RequestBody UpdateScanPayOrderRequest r){return service.updateOrder(id,r);}}
